import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Modèle de plugin ATLAS","description":"Créer un plugin ATLAS à partir du modèle GitHub officiel.","frontmatter":{"title":"Modèle de plugin ATLAS","description":"Créer un plugin ATLAS à partir du modèle GitHub officiel."},"headers":[],"relativePath":"fr/projects/atlas-plugins/plugin-template.md","filePath":"fr/projects/atlas-plugins/plugin-template.md","lastUpdated":1792840662000}'),n={name:"fr/projects/atlas-plugins/plugin-template.md"};function l(r,e,o,u,p,d){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="modele-de-plugin-atlas" tabindex="-1">Modèle de plugin ATLAS <a class="header-anchor" href="#modele-de-plugin-atlas" aria-label="Permalink to &quot;Modèle de plugin ATLAS&quot;">​</a></h1><p>Le <a href="https://github.com/rockbaer2007/atlas-plugin-template" target="_blank" rel="noreferrer">modèle officiel ATLAS Plugin Template sur GitHub</a> fournit un dépôt prêt à l&#39;emploi pour un plugin ATLAS. Utilisez <strong>Use this template</strong> sur GitHub pour créer votre propre dépôt.</p><h2 id="generateur-de-plugins-dans-l-administration" tabindex="-1">Générateur de plugins dans l&#39;Administration <a class="header-anchor" href="#generateur-de-plugins-dans-l-administration" aria-label="Permalink to &quot;Générateur de plugins dans l&#39;Administration&quot;">​</a></h2><p>L’Administration ATLAS propose un générateur pour identifiant, nom, description, version, chemin d’entrée et capacités. Choisir une icône MDI du catalogue local ou un PNG personnel jusqu’à 512 KiB ; le paquet inclut image et mentions de licence nécessaires. Couleurs et transparence du PNG sont conservées. Il génère une base HTML/CSS/JavaScript modifiable, un paquet, <code>repository.json</code> et un <code>README.md</code> localisé, également téléchargeable séparément. Vérifier contenus et chemins avant publication. Aucun dépôt GitHub ni publication automatique n’est créé. Les paquets importés pris en charge sont installés sur le serveur App après contrôle de compatibilité et servis sous <code>/plugin-assets/&lt;slug&gt;/</code>. Leur interface s’exécute à l’ouverture dans le navigateur ; les hooks Runtime ne sont pas enregistrés automatiquement. Garder <code>entry</code> et chemins du paquet cohérents.</p><p>Les plugins qui proposent leur propre choix de langue reprennent la préférence ATLAS enregistrée à leur ouverture. Le paramètre <code>language</code> de l&#39;URL du plugin est prioritaire. Si un plugin ne prend pas en charge la langue choisie, il utilise sa langue de repli configurée.</p><h2 id="demarrage-rapide" tabindex="-1">Démarrage rapide <a class="header-anchor" href="#demarrage-rapide" aria-label="Permalink to &quot;Démarrage rapide&quot;">​</a></h2><ol><li><p>Ouvrez le dépôt du modèle, puis choisissez <strong>Use this template</strong> → <strong>Create a new repository</strong>.</p></li><li><p>Clonez votre nouveau dépôt et modifiez <code>plugins/atlas-plugin/atlas-plugin.json</code>. Définissez un identifiant unique, un nom, une version, une description et uniquement les capacités réellement nécessaires.</p></li><li><p>Remplacez l&#39;application d&#39;exemple dans <code>plugins/atlas-plugin/</code>, puis remplacez <code>icon.svg</code>, <code>logo.svg</code> et <code>preview.svg</code> par les ressources de votre plugin.</p></li><li><p>Générez et validez le paquet localement :</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>Adaptez <code>repository.json</code> et <code>install.html</code> à votre dépôt. Le générateur reprend l&#39;identifiant, le nom, la version, les descriptions et les chemins des ressources du manifeste afin de synchroniser le catalogue.</p></li><li><p>Après le push, le catalogue est accessible à <code>https://raw.githubusercontent.com/&lt;owner&gt;/&lt;repo&gt;/main/repository.json</code> sans GitHub Pages. Activer Pages séparément pour publier <code>install.html</code> si souhaité.</p></li><li><p>Ajoutez l&#39;URL du catalogue dans l&#39;Administration ATLAS et installez le plugin pour le tester.</p></li></ol><h2 id="contenu-du-modele" tabindex="-1">Contenu du modèle <a class="header-anchor" href="#contenu-du-modele" aria-label="Permalink to &quot;Contenu du modèle&quot;">​</a></h2><p>Le modèle comprend un petit plugin d&#39;exemple, son manifeste, un catalogue, une page d&#39;installation, un générateur de paquet, des validations et un workflow GitHub Actions. Ce workflow lance la génération et les contrôles à chaque push et pull request.</p><p>Augmentez la version du plugin pour chaque publication, puis exécutez <code>npm run build</code>. Conservez l&#39;identifiant du plugin après sa publication. Vérifiez les autorisations et les capacités déclarées avant la mise en ligne.</p><h2 id="limites-actuelles-de-l-installation" tabindex="-1">Limites actuelles de l&#39;installation <a class="header-anchor" href="#limites-actuelles-de-l-installation" aria-label="Permalink to &quot;Limites actuelles de l&#39;installation&quot;">​</a></h2><p>Le serveur App installe les paquets validés, depuis un dépôt ou un import, dans le stockage persistant et sert les fichiers web sous <code>/plugin-assets/&lt;slug&gt;/</code>. Leur JavaScript s’exécute dans le navigateur à l’ouverture ; les modules Node ou hooks Runtime ne sont pas enregistrés automatiquement. Ce n’est pas une sandbox : vérifier paquet et code avant ouverture. Les fichiers contiennent du texte ou des ressources Base64 explicitement marquées ; maximum 300 fichiers et 20 MB par paquet. Héberger séparément les gros fichiers binaires.</p><p>Consultez <a href="./repository-format">Format du dépôt</a> pour les détails du catalogue et du paquet. Dépôt du modèle : <a href="https://github.com/rockbaer2007/atlas-plugin-template" target="_blank" rel="noreferrer">rockbaer2007/atlas-plugin-template</a>.</p>`,13)])])}const m=t(n,[["render",l]]);export{g as __pageData,m as default};
